css:
/* Dark Mode Card CSS */
.card {
  width: fit-content;
  background-color: #1e1e1e;
  border-radius: 0.75em;
  cursor: pointer;
  transition: ease 0.2s;
  box-shadow:
    1em 1em 1em rgba(0, 0, 0, 0.2),
    -0.75em -0.75em 1em rgba(255, 255, 255, 0.05);
  border: 1.5px solid #2a2a2a;
}

.card:hover {
  background-color: #2a2a2a;
  border: 1.5px solid #3a8bff;
}

.container {
  margin-top: 1.25em;
  margin-bottom: 1.375em;
  margin-left: 1.375em;
  margin-right: 2em;
  display: flex;
  flex-direction: row;
  gap: 0.75em;
}

.status-ind {
  width: 0.625em;
  height: 0.625em;
  background-color: #ff3333;
  margin: 0.375em 0;
  border-radius: 0.5em;
}

.text-wrap {
  display: flex;
  flex-direction: column;
  gap: 0.25em;
  color: #e0e0e0;
}

.time {
  font-size: 0.875em;
  color: #a0a0a0;
}

.text-link {
  font-weight: 500;
  text-decoration: none;
  color: #ffffff;
}

.button-wrap {
  display: flex;
  flex-direction: row;
  gap: 1em;
  align-items: center;
}

.secondary-cta {
  background-color: transparent;
  border: none;
  font-size: 15px;
  font-weight: 400;
  color: #b0b0b0;
  cursor: pointer;
}

.primary-cta {
  font-size: 15px;
  background-color: transparent;
  font-weight: 600;
  color: #3a8bff;
  border: none;
  border-radius: 1.5em;
  cursor: pointer;
}

button:hover {
  text-decoration: underline;
}

.right {
  display: flex;
  flex-direction: column;
  gap: 0.875em;
}
